INSERT INTO `articles` VALUES (2,NULL,'Giảm giá sốc cuối năm 2026','<h1>hi<span style=\"color:#000000\">&nbsp;asfasd &aacute;d<span style=\"font-family:Comic Sans MS,cursive\">sd&nbsp; asdasd&nbsp;&nbsp;</span><span style=\"font-family:Courier New,Courier,monospace\">sd da<span style=\"font-size:10px\">&aacute;d</span></span></span></h1>','https://res.cloudinary.com/dvqrzfu2f/image/upload/v1768034368/cld_14605786125034745820.jpg','published','2026-01-10 08:39:00','2026-01-17 08:39:00','2026-01-10 15:39:29'),(4,2,'Giảm giá sốc 60%','<p>ADAMIN</p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">sadsasfds</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS, cursive\"><span style=\"font-size:22px\">&aacute;dasdasaASSAF</span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','https://res.cloudinary.com/dvqrzfu2f/image/upload/v1769272044/cld_13977440087190826668.jpg','published','2026-01-15 16:32:00','2026-01-31 16:32:00','2026-01-24 23:27:22'),(5,3,'Giảm giá','<p>giảm gi&aacute;</p>','https://res.cloudinary.com/dvqrzfu2f/image/upload/v1769272138/cld_9012729921597262048.jpg','published','2026-01-05 16:28:00','2026-01-31 16:28:00','2026-01-24 23:28:56'),(6,3,'Tết tưng bừng - Ưu đãi cực lớn tới 60%','<p><strong>? Tri &Acirc;n Kh&aacute;ch H&agrave;ng &ndash; Tết Đ&oacute;n Sắc Việt ?</strong><br />\r\nViệt Sắc Đỏ tr&acirc;n trọng gửi đến Qu&yacute; kh&aacute;ch chương tr&igrave;nh <strong>ưu đ&atilde;i đặc biệt l&ecirc;n đến 60%</strong> cho bộ sưu tập <strong>&Aacute;o D&agrave;i Tết</strong>.</p>\r\n\r\n<p>Những thiết kế tinh tế, form d&aacute;ng chuẩn mực, chất liệu cao cấp, mang hơi thở văn h&oacute;a truyền thống h&ograve;a quyện c&ugrave;ng phong c&aacute;ch hiện đại &ndash; gi&uacute;p n&agrave;ng nổi bật trong từng khoảnh khắc đo&agrave;n vi&ecirc;n.</p>\r\n\r\n<p><strong>? Ưu đ&atilde;i &aacute;p dụng cho:</strong><br />\r\n✔ &Aacute;o d&agrave;i c&aacute;ch t&acirc;n<br />\r\n✔ &Aacute;o d&agrave;i truyền thống<br />\r\n✔ BST Tết xu&acirc;n &ndash; mẫu mới 2025</p>\r\n\r\n<p><strong>⏳ Thời gian ưu đ&atilde;i c&oacute; hạn, nhanh tay săn ngay!</strong><br />\r\nTết n&agrave;y h&atilde;y để Việt Sắc Đỏ c&ugrave;ng bạn lưu giữ những khoảnh khắc rực rỡ nhất.</p>','https://res.cloudinary.com/dvqrzfu2f/image/upload/v1769486385/cld_7773689588197522532.jpg','published','2026-01-28 03:59:00','2026-01-31 03:59:00','2026-01-27 10:59:46'),(7,5,'Tết tưng bừng - Ưu đãi cực lớn tới 30%','<p><strong>? TRI &Acirc;N KH&Aacute;CH H&Agrave;NG &ndash; TẾT B&Iacute;NH NGỌ: Đ&Oacute;N SẮC VIỆT, KHỞI VẬN MAY ?</strong></p>\r\n\r\n<p>Ch&agrave;o đ&oacute;n năm mới <strong>2026</strong>, <strong>Việt Sắc Đỏ</strong> tr&acirc;n trọng gửi tới Qu&yacute; kh&aacute;ch lời ch&uacute;c Khởi đầu Thuận lợi &ndash; Vạn sự Như &yacute;. Để tri &acirc;n sự đồng h&agrave;nh của n&agrave;ng trong suốt năm qua, ch&uacute;ng m&igrave;nh mang đến chương tr&igrave;nh ưu đ&atilde;i lớn nhất năm:</p>\r\n\r\n<p>✨ <strong>ƯU Đ&Atilde;I L&Ecirc;N ĐẾN 10% &ndash; TRỌN BỘ SƯU TẬP &Aacute;O D&Agrave;I TẾT 2026</strong> ✨</p>\r\n\r\n<p>Mỗi t&agrave; &aacute;o trong BST năm nay kh&ocirc;ng chỉ l&agrave; trang phục, m&agrave; l&agrave; một t&aacute;c phẩm nghệ thuật:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Chất liệu cao cấp:</strong> Silk, Linen, Gấm thượng hạng đem lại cảm gi&aacute;c mềm mại, qu&yacute; ph&aacute;i.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Thiết kế tinh xảo:</strong> Họa tiết th&ecirc;u tay thủ c&ocirc;ng, form d&aacute;ng t&ocirc;n vinh đường n&eacute;t &Aacute; Đ&ocirc;ng.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Phong c&aacute;ch đa dạng:</strong> Từ n&eacute;t cổ điển của &Aacute;o d&agrave;i Truyền thống đến sự trẻ trung của &Aacute;o d&agrave;i C&aacute;ch t&acirc;n.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>? <strong>Danh mục ưu đ&atilde;i đặc biệt: &Aacute;o d&agrave;i tuyền thống (giảm 30%)</strong></p>\r\n\r\n<p>⏳ <strong>Thời gian c&oacute; hạn:</strong> Chỉ từ nay đến hết 29 Tết. ? <em>Nhanh tay sở hữu t&agrave; &aacute;o may mắn để tỏa s&aacute;ng trong những ng&agrave;y đầu năm!</em></p>','https://res.cloudinary.com/dvqrzfu2f/image/upload/v1769610208/cld_2470796020377977116.png','published','2026-01-28 21:23:00','2026-01-16 21:24:00','2026-01-28 21:23:31');
