INSERT INTO `policy` VALUES (2,16,'Việt Sắc Đỏ hỗ trợ đổi size 1 lần duy nhất, không hỗ trợ đổi màu hoặc đổi sang mẫu sản phẩm khác.\nThời hạn đổi trong vòng 05 ngày kể từ ngày mua hàng.\nSản phẩm khi đổi cần còn hóa đơn, chưa giặt, chưa sử dụng, không có mùi lạ, không bị hư hỏng, và còn đầy đủ nhãn mác/tem tag.\nViệt Sắc Đỏ chỉ hỗ trợ đổi khi có hàng cùng mẫu, không hỗ trợ trả hàng hoàn tiền trong trường hợp khách đổi size.\nTrường hợp sản phẩm lỗi kỹ thuật do nhà sản xuất hoặc giao nhầm, Việt Sắc Đỏ hỗ trợ đổi mẫu tương đương hoặc hoàn tiền nếu không có sản phẩm thay thế. Thời gian hoàn tiền từ 1–2 ngày làm việc sau khi xác nhận sản phẩm đạt điều kiện.\nKhách hàng vui lòng thông báo trước khi đổi để được hỗ trợ. Nếu đổi từ xa, khách hàng vui lòng thanh toán phí vận chuyển 2 chiều.\nKhông áp dụng đổi/trả với sản phẩm đang SALE hoặc giảm giá.','2026-01-28 04:16:33'),(3,42,'Việt Sắc Đỏ hỗ trợ đổi size 1 lần duy nhất trong vòng 05 ngày kể từ ngày mua.\nKhông hỗ trợ đổi sang mẫu khác hoặc hoàn tiền nếu chỉ đổi size.\nSản phẩm phải còn nguyên tag, chưa sử dụng, đế chưa trầy xước, không bám bẩn.\nTrường hợp lỗi kỹ thuật hoặc giao nhầm, có thể hoàn tiền sau kiểm tra trong 1–2 ngày làm việc.\nKhông áp dụng đổi/trả cho sản phẩm SALE.\nNếu đổi từ xa, khách hàng thanh toán phí vận chuyển 2 chiều.','2026-01-28 04:18:50'),(4,56,'Việt Sắc Đỏ hỗ trợ đổi size 1 lần duy nhất, không hỗ trợ đổi màu hoặc đổi sang mẫu sản phẩm khác.\nThời hạn đổi trong vòng 05 ngày kể từ ngày mua hàng.\nSản phẩm khi đổi cần còn hóa đơn, chưa giặt, chưa sử dụng, không có mùi lạ, không bị hư hỏng, và còn đầy đủ nhãn mác/tem tag.\nViệt Sắc Đỏ chỉ hỗ trợ đổi khi có hàng cùng mẫu, không hỗ trợ trả hàng hoàn tiền trong trường hợp khách đổi size.\nTrường hợp sản phẩm lỗi kỹ thuật do nhà sản xuất hoặc giao nhầm, Việt Sắc Đỏ hỗ trợ đổi mẫu tương đương hoặc hoàn tiền nếu không có sản phẩm thay thế. Thời gian hoàn tiền từ 1–2 ngày làm việc sau khi xác nhận sản phẩm đạt điều kiện.\nKhách hàng vui lòng thông báo tr